import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Psychology is the scientific study of mind and behavior. Its methods matter as much as its findings.","blocks":[{"t":"key","text":"Perspectives: biological, behavioral, cognitive, psychodynamic, humanistic, sociocultural and evolutionary. Historical figures include Wundt (first lab), James (functionalism), Freud, Watson and Skinner (behaviorism), and Maslow and Rogers (humanism)."},{"t":"p","text":"Methods: case studies, naturalistic observation, surveys, correlational research (correlation coefficient r from −1 to +1; correlation isn't causation) and experiments, which manipulate an independent variable, measure a dependent variable, and use random assignment and control groups."},{"t":"p","text":"Ethics: informed consent, debriefing, confidentiality and review by an IRB."}]},{"say":"Behavior starts with neurons and the brain, which turn sensations into perceptions.","blocks":[{"t":"key","text":"Neurons communicate with action potentials (all-or-none) and neurotransmitters across synapses: dopamine (reward, movement), serotonin (mood), acetylcholine (muscles, memory), GABA (inhibition) and glutamate (excitation)."},{"t":"p","text":"Nervous system: central (brain and spinal cord) and peripheral (somatic and autonomic: sympathetic \"fight or flight,\" parasympathetic \"rest and digest\"). Brain areas: the frontal lobe (planning, Broca's area), parietal (touch), temporal (hearing, Wernicke's area), occipital (vision), cerebellum (coordination), hippocampus (memory) and amygdala (emotion)."},{"t":"p","text":"Sensation is detecting stimuli; perception is interpreting them. Concepts include thresholds, sensory adaptation, top-down versus bottom-up processing, and Gestalt principles."}]}],[{"say":"How do we learn, remember and change across the lifespan?","blocks":[{"t":"key","text":"Classical conditioning (Pavlov): a neutral stimulus paired with an unconditioned stimulus becomes a conditioned stimulus. Operant conditioning (Skinner): reinforcement increases behavior, punishment decreases it; schedules (fixed and variable ratio and interval) affect persistence. Observational learning (Bandura)."},{"t":"p","text":"Memory: encoding, storage and retrieval; sensory, short-term (about 7 ± 2 items) and long-term memory. Forgetting through decay and interference; memories are reconstructive and can be distorted."},{"t":"p","text":"Development: Piaget's stages (sensorimotor, preoperational, concrete operational, formal operational), attachment (Harlow, Ainsworth), and Erikson's psychosocial stages."}]},{"say":"Other people shape how we think and act, and psychology helps understand and treat mental illness.","blocks":[{"t":"key","text":"Social psychology: the fundamental attribution error (overemphasizing personality), cognitive dissonance, conformity (Asch), obedience (Milgram), the bystander effect, groupthink, and prejudice versus discrimination."},{"t":"p","text":"Psychological disorders are diagnosed with the DSM-5-TR: anxiety disorders, major depressive disorder, bipolar disorder, schizophrenia, OCD, PTSD and personality disorders. The biopsychosocial model considers biological, psychological and social causes."},{"t":"p","text":"Therapies: psychodynamic, humanistic (client-centered), behavioral (exposure, systematic desensitization), cognitive and CBT, group therapy, and biomedical treatments (antidepressants such as SSRIs, antipsychotics)."}]}]];
export default text;
